@public create table varagg as (key string primary key, total sum(int))
into table varagg select sum(intPrimitive) as total from SupportBean group by theString
@name('s0') select (select total from varagg where key = s0.p00) as value from SupportBean_S0 as s0

@public create table InfraOne (string string, intPrimitive int)
@name('s0') select (select intPrimitive from InfraOne where string = s0.p00) as c0 from SupportBean_S0 as s0
insert into InfraOne select theString as string, intPrimitive from SupportBean

@public create table MyTable(k0 string primary key, k1 string primary key, p2 string, value int)
create index MyIndex on MyTable(p2)
on SupportBean_S0 merge MyTable where p00 = k0 and p01 = k1 when not matched then insert select p00 as k0, p01 as k1, p02 as p2, id as value when matched then update set p2 = p02, value = id 
@Name('s0') select (select value from MyTable as tbl where sb.theString = tbl.p2) as c0 from SupportBean as sb

create table MyTable(tablecol string primary key);
insert into MyTable select p00 as tablecol from SupportBean_S0;
@name('s0') select * from SupportBean(theString=(select tablecol from MyTable).orderBy().firstOf())

